diff --git a/cmd/entire/cli/agent/agent.go b/cmd/entire/cli/agent/agent.go
index 73f548e4..b1532f43 100644
--- a/cmd/entire/cli/agent/agent.go
+++ b/cmd/entire/cli/agent/agent.go
@@ -202,6 +202,29 @@ type SidecarImageProvider interface {
 	SidecarImages(ctx context.Context, sessionRef string) ([]CompactedTranscriptAsset, error)
 }

+// TranscriptSanitizer is implemented by agents whose native transcript format
+// carries state that Entire must not keep in its own copy — e.g. Codex rollouts
+// embed encrypted reasoning payloads and compaction blobs that are bound to the
+// originating session and cannot be replayed out of a checkpoint.
+//
+// Entire always leaves the agent's own transcript untouched; this transform applies
+// only to the copy Entire stores. Sanitizing before redaction is what keeps
+// non-replayable payloads out of storage AND keeps the redaction layers from
+// scanning megabytes of ciphertext they would only discard afterwards (base64 is
+// the pathological input for the entropy layer).
+//
+// Implementations must be pure byte transforms: idempotent (sanitizing an
+// already-sanitized transcript is a no-op), safe to call from hooks, and never
+// dependent on the agent process being alive.
+type TranscriptSanitizer interface {
+	Agent
+
+	// SanitizeTranscriptForStorage returns the transcript with non-portable state
+	// removed. It must return the input unchanged rather than nil when it cannot
+	// parse the transcript, so a sanitizer failure never loses the session.
+	SanitizeTranscriptForStorage(data []byte) []byte
+}
+
 // TokenCalculator provides token usage calculation for a session.
 // The framework calls this during step save and checkpoint if implemented.
 type TokenCalculator interface {
diff --git a/cmd/entire/cli/agent/capabilities.go b/cmd/entire/cli/agent/capabilities.go
index 9c4ed549..77bbe98d 100644
--- a/cmd/entire/cli/agent/capabilities.go
+++ b/cmd/entire/cli/agent/capabilities.go
@@ -17,9 +17,10 @@ type CapabilityDeclarer interface {
 // can deserialize directly into this type.
 //
 // Not every optional interface appears here: built-in-only capabilities that
-// have no external-protocol equivalent (SessionBaseDirProvider, ModelExtractor)
-// are intentionally excluded — their As* helpers resolve by type assertion
-// alone, with no DeclaredCaps gate.
+// have no external-protocol equivalent (SessionBaseDirProvider, ModelExtractor,
+// SkillEventExtractor, TranscriptSanitizer) are intentionally excluded — their
+// As* helpers resolve by type assertion alone (see builtinCapability), with no
+// DeclaredCaps gate.
 type DeclaredCaps struct {
 	Hooks                  bool `json:"hooks"`
 	TranscriptAnalyzer     bool `json:"transcript_analyzer"`
@@ -89,6 +90,35 @@ func AsSidecarImageProvider(ag Agent) (SidecarImageProvider, bool) {
 	return p, ok
 }

+// AsTranscriptSanitizer returns the agent as TranscriptSanitizer if it implements
+// the interface. This is a pure local byte transform with no external process to
+// negotiate with, so it needs no DeclaredCaps gate.
+func AsTranscriptSanitizer(ag Agent) (TranscriptSanitizer, bool) {
+	return builtinCapability[TranscriptSanitizer](ag)
+}
+
+// SanitizeTranscriptForStorage applies the agent's storage sanitizer when it has one
+// and returns data unchanged otherwise. Every path that stores a transcript copy
+// should call this BEFORE redaction — see TranscriptSanitizer for why. A no-op for
+// agents without the capability and idempotent for those with it, so it is safe to
+// call on any transcript from any path.
+func SanitizeTranscriptForStorage(ag Agent, data []byte) []byte {
+	if len(data) == 0 {
+		return data
+	}
+	s, ok := AsTranscriptSanitizer(ag)
+	if !ok {
+		return data
+	}
+	sanitized := s.SanitizeTranscriptForStorage(data)
+	if sanitized == nil {
+		// Defensive: the interface forbids this, but a nil return would silently
+		// drop the whole session. Prefer the unsanitized transcript over none.
+		return data
+	}
+	return sanitized
+}
+
 // AsTokenCalculator returns the agent as TokenCalculator if it both
 // implements the interface and (for CapabilityDeclarer agents) has declared the capability.
 func AsTokenCalculator(ag Agent) (TokenCalculator, bool) {
diff --git a/cmd/entire/cli/agent/codex/codex.go b/cmd/entire/cli/agent/codex/codex.go
index e322e269..22a8f7f4 100644
--- a/cmd/entire/cli/agent/codex/codex.go
+++ b/cmd/entire/cli/agent/codex/codex.go
@@ -175,7 +175,7 @@ func (c *CodexAgent) WriteSession(_ context.Context, session *agent.AgentSession
 		return errors.New("session has no native data to write")
 	}

-	dataToWrite := sanitizeRestoredTranscript(session.NativeData)
+	dataToWrite := SanitizePortableTranscript(session.NativeData)
 	if err := os.WriteFile(session.SessionRef, dataToWrite, 0o600); err != nil {
 		return fmt.Errorf("failed to write transcript: %w", err)
 	}
diff --git a/cmd/entire/cli/agent/codex/transcript.go b/cmd/entire/cli/agent/codex/transcript.go
index 16b04f55..3c98d9f7 100644
--- a/cmd/entire/cli/agent/codex/transcript.go
+++ b/cmd/entire/cli/agent/codex/transcript.go
@@ -22,6 +22,7 @@ var (
 	_ agent.TokenCalculator             = (*CodexAgent)(nil)
 	_ agent.PromptExtractor             = (*CodexAgent)(nil)
 	_ agent.RestoredSessionPathResolver = (*CodexAgent)(nil)
+	_ agent.TranscriptSanitizer         = (*CodexAgent)(nil)
 )

 // rolloutLine is the top-level JSONL line structure in Codex rollout files.
@@ -386,27 +387,71 @@ func (c *CodexAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string
 // replayed when Entire reconstructs a Codex rollout outside its original
 // session context.
 func SanitizePortableTranscript(data []byte) []byte {
+	if !mayNeedSanitizing(data) {
+		return data
+	}
+
 	lines := splitJSONL(data)
 	if len(lines) == 0 {
 		return data
 	}

 	sanitized := make([][]byte, 0, len(lines))
+	changed := false
 	for _, lineData := range lines {
 		updated, keep := sanitizeRolloutLine(lineData)
 		if !keep {
+			changed = true
 			continue
 		}
+		if !bytes.Equal(updated, lineData) {
+			changed = true
+		}
 		sanitized = append(sanitized, updated)
 	}

+	// Nothing to strip: hand back the original bytes rather than paying the
+	// reassembly copy. Callers rely on this being cheap — sanitization is
+	// idempotent precisely so every storage path can call it without tracking
+	// whether an upstream path already did.
+	if !changed {
+		return data
+	}
 	if len(sanitized) == 0 {
 		return data
 	}
 	return agent.ReassembleJSONL(sanitized)
 }

-func sanitizeRestoredTranscript(data []byte) []byte {
+// sanitizeMarkers are the substrings that gate every transformation
+// sanitizeRolloutLine performs: dropping "compaction"/"compaction_summary" items,
+// rewriting "compacted" lines, and deleting "encrypted_content" from "reasoning"
+// items. A transcript containing none of them cannot be altered, so one scan lets
+// us skip unmarshalling every line.
+//
+// Deliberately over-broad ("compact" covers compacted/compaction/
+// compaction_summary): a false positive just falls through to the full pass, while
+// a false negative would silently skip sanitization.
+var sanitizeMarkers = [][]byte{
+	[]byte("encrypted_content"),
+	[]byte("compact"),
+	[]byte("reasoning"),
+}
+
+func mayNeedSanitizing(data []byte) bool {
+	for _, marker := range sanitizeMarkers {
+		if bytes.Contains(data, marker) {
+			return true
+		}
+	}
+	return false
+}
+
+// SanitizeTranscriptForStorage implements agent.TranscriptSanitizer. Codex rollouts
+// embed encrypted reasoning payloads and compaction blobs that are bound to the
+// originating session, so Entire strips them from its stored copy while leaving
+// Codex's own rollout file untouched.
+func (c *CodexAgent) SanitizeTranscriptForStorage(data []byte) []byte {
 	return SanitizePortableTranscript(data)
 }

@@ -432,10 +477,18 @@ func sanitizeRolloutLine(lineData []byte) ([]byte, bool) {
 		return lineData, true
 	}
 	switch itemType {
-	case "reasoning":
+	case "reasoning", "compaction", "compaction_summary":
+		// Strip the non-replayable payload but KEEP the line. Dropping these lines
+		// (as this used to) shortened the stored transcript relative to the agent's
+		// rollout, while CheckpointTranscriptStart is counted on the rollout — so
+		// every offset into a stored Codex transcript was off by the number of
+		// dropped lines before it. Stripping in place keeps the two line numberings
+		// identical, which is what the offset's five consumers assume.
+		//
+		// Nested compaction items inside a "compacted" line's replacement_history
+		// are still removed outright (see sanitizeHistoryItems): those are array
+		// elements within a single line, so removing them cannot shift line numbers.
 		delete(payload, "encrypted_content")
-	case "compaction", "compaction_summary":
-		return nil, false
 	default:
 		return lineData, true
 	}

